-- 每个中介只能在自己所在的城市发布房源

-- 2. 客户表 (sys_customer) - ID 从 10 开始

-- 3. 房源表 (h_house) - ID 从 26 开始
-- 北京: 26-45 (20条) - 由北京中介(agent_id 11-13)发布

-- 上海房源: 46-65 (20条) - 由上海中介(agent_id 14-16)发布

-- 广州房源: 66-75 (10条) - 由广州中介(agent_id 17-18)发布

-- 深圳房源: 76-83 (8条) - 由深圳中介(agent_id 19-20)发布

-- 杭州房源: 84-88 (5条) - 由杭州中介(agent_id 21)发布

-- 4. 带看记录表 (h_viewing) - ID 从 23 开始

-- 5. 交易表 (h_transaction) - ID 从 12 开始

-- 更新交易成功的房源状态
-- 当交易状态为3(已完成)时，将房源状态更新为2(已成交)
UPDATE h_house SET house_status = 2 WHERE house_id IN (
    SELECT house_id FROM h_transaction WHERE transaction_status = 3
);

